  "-rw-r--r--   1 0        0             512 Oct  1  1997 README\r\n"
  "-rw-r--r--   1 0        0             512 Oct  1  1997 README2\r\n";

static void sendall(int fd, const char *s){ (void)!write(fd, s, strlen(s)); }

static void *data_conn_listener(void *proto_param_less){
  (void)proto_param_less;
  int ls = socket(AF_INET, SOCK_STREAM, 0);
  int one=1; setsockopt(ls, SOL_SOCKET, SO_REUSEADDR, &one, sizeof(one));
  struct sockaddr_in a={0};
  a.sin_family=AF_INET; a.sin_port=htons(DATA_PORT);
  inet_pton(AF_INET, "127.0.0.1", &a.sin_addr);
