/* Minimal faithful re-implementation of curl_fuzzer's legacy FTP harness:
 * parses the TLV PoC file, routes protocol bytes through socketpairs via
 * CURLOPT_OPENSOCKETFUNCTION, and drives the transfer with curl_multi —
 * mirroring fuzz_open_socket / fuzz_handle_transfer. */
#include <curl/curl.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/socket.h>
#include <sys/select.h>

struct chunk { const uint8_t *p; size_t n; size_t sent; };
static struct chunk ctrl_chunks[16]; static int n_ctrl=0;
static struct chunk data_chunks[4]; static int n_data=0;
static char g_url[512]; static long g_wild=0;
static int srv[2]={-1,-1};      /* server-side ends: 0=control, 1=data */
static int fed_idx[2]={0,0};    /* next chunk to feed per slot */
static int data_shut=0;

static uint16_t rd16(const uint8_t*b){return (b[0]<<8)|b[1];}
static uint32_t rd32(const uint8_t*b){return ((uint32_t)b[0]<<24)|((uint32_t)b[1]<<16)|((uint32_t)b[2]<<8)|b[3];}

static void parse_tlvs(const uint8_t *d, size_t n){
  size_t pos=0;
  while(pos+6<=n){
    uint16_t t=rd16(d+pos); uint32_t l=rd32(d+pos+2); pos+=6;
    if(pos+l>n) { fprintf(stderr,"bad tlv\n"); exit(2); }
    const uint8_t *v=d+pos;
    if(t==0x0001){ size_t c=l<sizeof(g_url)-1?l:sizeof(g_url)-1; memcpy(g_url,v,c); g_url[c]=0; }
    else if(t==0x0021){ g_wild=rd32(v); }
    else if(t==0x001F){ data_chunks[n_data].p=v; data_chunks[n_data].n=l; data_chunks[n_data].sent=0; n_data++; }
    else if((t==0x0002)||(t>=0x0011&&t<=0x001A)){ ctrl_chunks[n_ctrl].p=v; ctrl_chunks[n_ctrl].n=l; ctrl_chunks[n_ctrl].sent=0; n_ctrl++; }
    pos+=l;
  }
}

static curl_socket_t open_socket(void *ptr, curlsocktype purp, struct curl_sockaddr *addr){
  (void)ptr;(void)purp;(void)addr;
  int fds[2];
  if(socketpair(AF_UNIX,SOCK_STREAM,0,fds)) return CURL_SOCKET_BAD;
  int idx = (srv[0]==-1)?0:1;
  if(idx==1 && srv[1]!=-1){ close(fds[0]); close(fds[1]); return CURL_SOCKET_BAD; }
  srv[idx]=fds[0];
  int fl=fcntl(fds[1],F_GETFL); fcntl(fds[1],F_SETFL,fl|O_NONBLOCK);
  fl=fcntl(fds[0],F_GETFL); fcntl(fds[0],F_SETFL,fl|O_NONBLOCK);
  fprintf(stderr,"[harness] connection opened -> slot %d\n",idx);
  return fds[1];
}

/* try to push more scripted bytes into server ends */
static void feed_all(void){
  for(int idx=0; idx<2; idx++){
    if(srv[idx]==-1) continue;
    struct chunk *arr = idx? data_chunks:ctrl_chunks;
    int cnt = idx? n_data:n_ctrl;
    while(fed_idx[idx]<cnt){
      struct chunk *c=&arr[fed_idx[idx]];
      ssize_t w=write(srv[idx], c->p+c->sent, c->n-c->sent);
      if(w>0){ c->sent+=w; if(c->sent==c->n){ fed_idx[idx]++; } continue; }
      if(w<0 && (errno==EAGAIN||errno==EWOULDBLOCK)) break;
      break;
    }
    if(idx==1 && fed_idx[1]>=n_data && n_data>0 && !data_shut){
      shutdown(srv[1],SHUT_WR); data_shut=1;
      fprintf(stderr,"[harness] data channel fully sent, EOF\n");
    }
  }
}

int main(int argc, char**argv){
  if(argc<2){fprintf(stderr,"usage: %s tlv_poc\n",argv[0]); return 2;}
  FILE*f=fopen(argv[1],"rb"); if(!f){perror("open");return 2;}
  fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
  uint8_t *buf=malloc(n); fread(buf,1,n,f); fclose(f);
  parse_tlvs(buf,n);
  fprintf(stderr,"[harness] url=%s wildcard=%ld ctrl_chunks=%d data_chunks=%d\n",
          g_url,g_wild,n_ctrl,n_data);

  CURL *easy=curl_easy_init();
  curl_easy_setopt(easy,CURLOPT_URL,g_url);
  curl_easy_setopt(easy,CURLOPT_WILDCARDMATCH,g_wild);
  curl_easy_setopt(easy,CURLOPT_OPENSOCKETFUNCTION,open_socket);
  curl_easy_setopt(easy,CURLOPT_CONNECT_TO,NULL); /* loopback intercept via opensocket hook */
  curl_easy_setopt(easy,CURLOPT_TIMEOUT_MS,10000L);
  curl_easy_setopt(easy,CURLOPT_SERVER_RESPONSE_TIMEOUT,5L);
  curl_easy_setopt(easy,CURLOPT_VERBOSE,0L);

  CURLM *multi=curl_multi_init();
  curl_multi_add_handle(multi,easy);
  int still=0, idle=0;
  curl_multi_perform(multi,&still);
  while(still){
    feed_all();
    fd_set rd,wr,ex; FD_ZERO(&rd);FD_ZERO(&wr);FD_ZERO(&ex);
    int maxfd=-1; long to=100;
    curl_multi_timeout(multi,&to);
    curl_multi_fdset(multi,&rd,&wr,&ex,&maxfd);
    for(int i=0;i<2;i++) if(srv[i]!=-1){ FD_SET(srv[i],&wr); FD_SET(srv[i],&rd); if(srv[i]>maxfd)maxfd=srv[i]; }
    struct timeval tv; tv.tv_sec=0; tv.tv_usec=20000;
    select(maxfd+1,&rd,&wr,&ex,&tv);
    feed_all();
    int prev=still;
    curl_multi_perform(multi,&still);
    idle = (still==prev)? idle+1:0;
    if(idle>2500){ fprintf(stderr,"[harness] stalled, aborting\n"); break; }
  }
  feed_all();
  int msgn=0; CURLMsg *m;
  while((m=curl_multi_info_read(multi,&msgn))){
    if(m->msg==CURLMSG_DONE){
      fprintf(stderr,"[harness] DONE rc=%d (%s)\n",m->data.result,curl_easy_strerror(m->data.result));
    }
  }
  curl_multi_remove_handle(multi,easy);
  curl_multi_cleanup(multi); curl_easy_cleanup(easy);
  return 0;
}
EOF
